-- Sol, además de propósito e identidad, es la directora creativa del canal Aion (4-nov-2026): mentalismo, Jung, atención.
UPDATE agent_functions SET
  purpose = 'Propósito e identidad, y dirección creativa del canal Aion: gancho, suspenso, mentalismo honesto, simbolismo junguiano, movimiento y color; visión, objetivos y coherencia con los valores explícitos.',
  allowed_tools = ARRAY['resumen_negocios','buscar_notas','guardar_nota','buscar_conocimiento','buscar_informes','ver_resultado_tarea','estado_youtube','WebSearch','WebFetch'],
  charter = charter || E'\n\nDIRECCIÓN CREATIVA DEL CANAL AION (directora creativa):\n1. Antes de que Venus escriba un guion, escribes el brief creativo con el playbook yt-direccion-creativa y su skill direccion-creativa: apertura de 20 s, bucles abiertos, efectos de mentalismo, mapa de símbolos auténticos, movimiento y color, ritmo y revelación honesta.\n2. Usas la investigación guardada (guías de atención y de mentalismo y Jung, con fuentes y etiquetas de evidencia) y la contrastas con las cifras reales del canal.\n3. Es narración y psicología como entretenimiento: nunca afirmas leer mentes, predecir vidas, curar ni diagnosticar; Jung es un marco, no un hecho; ninguna mención de apps hasta 1.000 suscriptores y 4.000 horas.\nNunca: prometer resultados psíquicos o de salud, ni presentar la PNL o los «comandos embebidos» como técnica probada.'
WHERE id = 'sol';

-- Conocimiento de dirección creativa (resúmenes de docs/guia-atencion.md y docs/guia-mentalismo-jung.md) para buscar_conocimiento
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Atención en vídeo (Aion): apertura y bucles$t$, $c$Evidencia: YouTube pide atrapar con lo que dices o con un visual llamativo en los primeros 15 s, aclarar de qué trata, adelantar el premio y no usar intros de marca; título y miniatura deben prometer lo que da la apertura. Teoría de la brecha de información (Loewenstein 1994): la curiosidad nace al notar lo que falta y necesita contexto previo. Reglas: imagen llamativa + pregunta en 0-5 s; de qué trata en 5-20 s; 2-3 bucles abiertos en el primer minuto cerrados en orden; cada sección termina con una pregunta concreta; nunca prometer algo que no se entrega. Zeigarnik no es un mecanismo de memoria probado. Fuente: docs/guia-atencion.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Atención en vídeo (Aion): apertura y bucles$t$);
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Atención en vídeo (Aion): ritmo, color y movimiento$t$, $c$Evidencia moderada: cortes relacionados atraen atención y los no relacionados sobrecargan (Lang 1993); vídeos cortos y dibujo sobre pantalla retienen mejor (Guo 2014). No hay regla probada de 'cambiar algo cada N segundos'. Color: lo evidenciado es el CONTRASTE (un sujeto focal fuerte, Itti 1998); que el rojo o naranja suban retención o clics NO está probado: usarlos como decisión de diseño para tensión y energía. Reglas: alternar ritmo rápido y lento, cortes relacionados, corte brusco solo para la revelación, un sujeto focal por escena, probar miniaturas con 'Probar y comparar'. Fuente: docs/guia-atencion.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Atención en vídeo (Aion): ritmo, color y movimiento$t$);
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Shorts de Aion: suspenso de principio a fin$t$, $c$YouTube mide 'vistos vs deslizados'. Estructura: fotograma 1 llamativo y en movimiento + pregunta en pantalla (o predicción sellada); un solo misterio continuo con pista que sube; elección de tres opciones hacia el segundo 8; respuesta solo en los últimos 3 s; cero relleno, sin intro ni despedida; último fotograma que enlaza con el primero (bucle, práctica de creadores, no regla oficial). Si enlaza a un largo, el largo abre cumpliendo el gancho. Medir contra el historial propio. Fuentes: docs/guia-atencion.md y docs/guia-mentalismo-jung.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Shorts de Aion: suspenso de principio a fin$t$);
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Mentalismo honesto para guiones (Aion)$t$, $c$Canon: Corinda (13 Steps to Mentalism), Banachek (Psychological Subtleties), Derren Brown (Tricks of the Mind), Annemann, Jermay, Maven (conocido solo por resúmenes). Principio: la presentación y el ritmo sostienen el efecto. Efectos útiles y honestos: predicción y revelación; elección forzada de tres puertas con premio en cada una; espejo Barnum (frases cálidas y universales ligadas a un símbolo, nunca un diagnóstico); conocimiento imposible con fuente en pantalla; serie de tres 'sí' honestos; bucles anidados; desvío de atención; ancla; interrupción de patrón; dualidad; cierre de pico y final; revelación honesta del truco. Evidencia: Barnum fuerte; priming conductual débil; PNL y 'comandos embebidos' sin respaldo (no usarlos ni afirmarlos). Ética: narración y psicología como entretenimiento, sin poderes psíquicos ni terapia. Fuente: docs/guia-mentalismo-jung.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Mentalismo honesto para guiones (Aion)$t$);
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Jung y símbolos para Aion (El hombre y sus símbolos, 1964)$t$, $c$Obra final de Jung para el gran público (con Henderson, von Franz, Jaffé y Jacobi). Conceptos: inconsciente colectivo, arquetipos, Sombra, ánima/ánimus, Persona, Sí-mismo, individuación; mandalas y sueños compensatorios. Lectura jungiana tradicional: sombra = lo rechazado; viejo sabio = sentido que guía; gran madre = nutre y devora; embaucador = desorden que lleva al cambio; héroe = búsqueda del yo; serpiente/uróboros = renovación; círculo/mandala = el Sí-mismo; árbol = crecimiento; agua = inconsciente; fuego = transformación; cuatro = totalidad. Teoría no demostrada: decir 'una lectura jungiana'. Código visual estable: sombra = índigo frío o ser rojo en el pico de tensión; Sí-mismo = círculo dorado solo en cierres; viejo sabio = violeta; embaucador = naranja; gran madre = verde y agua. Fuente: docs/guia-mentalismo-jung.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Jung y símbolos para Aion (El hombre y sus símbolos, 1964)$t$);
INSERT INTO knowledge_items (business_id, kind, topic, content, source, created_by)
  SELECT b.id, 'hecho', $t$Símbolos esotéricos auténticos (Aion)$t$, $c$Pentagrama: reconocimiento pitagórico, cinco llagas en el cristianismo medieval, pentáculo en la wicca. Uróboros: renovación cíclica, 'el todo es uno'. Ojo de la Providencia: cuidado de Dios (Renacimiento); el vínculo con los illuminati es teoría de la conspiración. Flor de la Vida: patrón antiguo, nombre y significados modernos (1999). Hexagrama: sello de Salomón; en alquimia reconcilia fuego y agua. Caduceo: bastón de Hermes, Mercurio alquímico (no la vara de Asclepio). Ankh: 'vida' egipcio. Glifos planetarios y metales: Sol-oro, Luna-plata, Mercurio-azogue, Venus-cobre, Marte-hierro, Júpiter-estaño, Saturno-plomo. Alquimia: nigredo, albedo, rubedo. Árbol de la Vida: diez sefirot y 22 caminos (no afirmar relación con el tarot). Fuente: docs/guia-atencion.md$c$, 'Investigación con fuentes, 4-nov-2026 (docs/)', 'sol'
  FROM (SELECT min(id) AS id FROM businesses) b
  WHERE b.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM knowledge_items WHERE topic = $t$Símbolos esotéricos auténticos (Aion)$t$);
